#!/bin/sh
set -eu; root=$(CDPATH= cd -- "$(dirname "$0")" && pwd); [ -f /etc/os-release ] || { echo "No /etc/os-release; cannot detect the distro." >&2; exit 1; }; . /etc/os-release; blob=" ${ID:-} ${ID_LIKE:-} "; case "$blob" in *" arch "*|*" endeavouros "*|*" manjaro "*|*" cachyos "*|*" garuda "*|*" artix "*) fam=pacman;; *" debian "*|*" ubuntu "*|*" linuxmint "*|*" pop "*|*" kali "*|*" parrot "*|*" elementary "*) fam=apt;; *" fedora "*|*" rhel "*|*" centos "*|*" nobara "*|*" rocky "*|*" almalinux "*) fam=dnf;; *" suse "*|*" sles "*|*" opensuse "*) fam=zypper;; *) echo "Unsupported distro: ${ID:-unknown}. Supports Arch, Debian/Ubuntu, Fedora/RHEL, and openSUSE." >&2; exit 1;; esac; arch=$(uname -m); case "$arch" in x86_64|aarch64) ;; *) echo "Unsupported CPU: $arch" >&2; exit 1;; esac; asroot() { if [ "$(id -u)" -eq 0 ]; then "$@"; else sudo "$@"; fi; }; case "$fam" in pacman) asroot pacman -S --needed --noconfirm python python-pyqt6 curl tar ca-certificates;; apt) asroot apt-get update; asroot apt-get install -y python3 python3-pyqt6 curl tar ca-certificates;; dnf) asroot dnf install -y python3 python3-pyqt6 curl tar ca-certificates;; zypper) asroot zypper --non-interactive install python3 python3-PyQt6 curl tar ca-certificates || asroot zypper --non-interactive install python3 python313-PyQt6 curl tar ca-certificates || asroot zypper --non-interactive install python3 python311-PyQt6 curl tar ca-certificates;; esac; ver=1.26.0; tmp=$(mktemp -d); trap 'rm -rf "$tmp"' EXIT; curl -fL --retry 3 -o "$tmp/od.tgz" "https://github.com/peetzweg/opendisplay/releases/download/v${ver}/od-sender-${arch}-unknown-linux-gnu.tar.gz"; tar -xzf "$tmp/od.tgz" -C "$tmp"; set -- "$tmp"/od-sender-*/install.sh; chmod +x "$1"; "$1"; if [ -f "$root/ipad-display" ] && [ -f "$root/ipad-display.desktop" ] && [ -f "$root/ipad-display.svg" ]; then src=$root; else mkdir -p "$tmp/app"; sed -n '/^#__PAYLOAD__$/,$p' "$0" | sed '1d; s/^# //' | base64 -d | tar -xz -C "$tmp/app"; src=$tmp/app; fi; install -D -m 755 "$src/ipad-display" "$HOME/.local/bin/ipad-display"; install -D -m 644 "$src/ipad-display.svg" "$HOME/.local/share/icons/hicolor/scalable/apps/ipad-display.svg"; mkdir -p "$HOME/.local/share/applications"; sed "s#@HOME@#$HOME#g" "$src/ipad-display.desktop" > "$HOME/.local/share/applications/ipad-display.desktop"; if command -v update-desktop-database >/dev/null 2>&1; then update-desktop-database "$HOME/.local/share/applications" || true; fi; if command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state >/dev/null 2>&1; then asroot firewall-cmd --add-service=mdns >/dev/null || true; asroot firewall-cmd --permanent --add-service=mdns >/dev/null || true; fi; echo "Installed. Open iPad Display from the menu, or run $HOME/.local/bin/ipad-display"
